/**
 * DB-free unit tests for the SQL fragment guard and the engine's identifier handling:
 * an injection corpus must be rejected, legitimate expressions must still pass, and the SQL generated by
 * generateSql never contains caller-controlled text outside quoted identifiers / validated fragments.
 */
import { assertSafeExpression, assertSafeSelectQuery, fieldToSql, quoteDotted, safeInt, validateAst, escapeAstLiterals, assertSafeName, SqlGuardError } from '../../utils/sqlGuard';

jest.mock('../../config/database', () => ({ pool: { connect: jest.fn(), query: jest.fn() }, queryWithContext: jest.fn(), tenantSearchPath: jest.fn() }));
import { QueryEngineService } from './query-engine.service';

const INJECTIONS = [
  "1; DROP TABLE users",
  "1; DROP TABLE users; --",
  "a -- comment",
  "a /* c */ + 1",
  "x' OR 1=1",
  "x' UNION SELECT 1",
  "x'; DELETE FROM t; --",
  'x" OR "1"="1',
  "(SELECT password_hash FROM public.users LIMIT 1)",
  "a UNION SELECT password_hash FROM public.users",
  "1) UNION SELECT 1 --",
  "pg_sleep(10)",
  "pg_read_file('/etc/passwd')",
  "set_config('app.tenant_id','other',false)",
  "current_setting('request.jwt.claims')",
  "dblink('host=evil','select 1')",
  "lo_import('/etc/passwd')",
  "COPY t TO PROGRAM 'id'",
  "a; RESET ROLE; DROP SCHEMA x CASCADE",
  "t.col; SELECT 1",
  "public.users.password_hash",
  "fabric_admin.audit_logs.new_data",
  "pg_catalog.pg_shadow.passwd",
  "tenant_victim.orders.secret",
  "$$ ; drop table x; $$",
  "a\\' OR 1=1",
  "a\u0000b",
  "`id`",
  "CASE WHEN (SELECT 1)=1 THEN 1 END",
  "1 = 1 OR EXISTS(SELECT 1)",
  "ANY(ARRAY[1,2])",
  "x::regclass",
  "a; select 1",
  "version()",
  "current_user",
  "session_user",
  "INSERT INTO x VALUES (1)",
  "grant all on x to public",
  "call fabric_admin.create_tenant_namespace('x')",
  "".padEnd(600, 'a'),
];

const LEGIT = [
  'COUNT(*)', 'SUM(amount)', 'sum(o.amount) AS total', 'COUNT(*) AS n', 'a.id = b.id', 'a.id = b.account_id AND b.status = \'ACTIVE\'',
  'lower(name)', 'COALESCE(a.x, 0) + 1', 'created_at >= now()', 'ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC)',
  'CASE WHEN x > 1 THEN 1 ELSE 0 END', 'CAST(x AS numeric(10,2))', 'amount * 1.5', 'price BETWEEN 1 AND 10', 'name LIKE \'a%\'', 'x IN (1, 2, 3)',
  'date_trunc(\'day\', created_at)', 'a || b', 'x IS NOT NULL',
];

describe('sqlGuard: free-form expressions', () => {
  it.each(INJECTIONS)('rejects %j', (bad) => {
    expect(() => assertSafeExpression(bad, 'expr')).toThrow(SqlGuardError);
  });
  it.each(LEGIT)('accepts %j', (ok) => {
    expect(assertSafeExpression(ok, 'expr')).toBe(ok.trim());
  });
  it('error carries HTTP 400 + code', () => {
    try { assertSafeExpression('1; drop table x'); fail('should throw'); } catch (e: any) { expect(e.status).toBe(400); expect(e.code).toBe('INVALID_SQL_FRAGMENT'); }
  });
  it('non-strings are rejected', () => {
    for (const v of [null, undefined, 1, {}, [], true]) expect(() => assertSafeExpression(v as any)).toThrow(SqlGuardError);
  });
  it('own-tenant qualifiers are allowed in query mode only for the caller\'s tenant', () => {
    expect(() => assertSafeSelectQuery('SELECT a.id FROM tenant_me.orders a WHERE a.id > 1', 'me')).not.toThrow();
    expect(() => assertSafeSelectQuery('SELECT a.id FROM tenant_other.orders a', 'me')).toThrow(SqlGuardError);
    expect(() => assertSafeSelectQuery('SELECT * FROM public.users', 'me')).toThrow(SqlGuardError);
    expect(() => assertSafeSelectQuery('SELECT 1; DROP TABLE x', 'me')).toThrow(SqlGuardError);
    expect(() => assertSafeSelectQuery('DELETE FROM x', 'me')).toThrow(SqlGuardError);
    expect(() => assertSafeSelectQuery('SELECT pg_sleep(5)', 'me')).toThrow(SqlGuardError);
    expect(assertSafeSelectQuery('SELECT id, SUM(x) FROM orders WHERE y = 1 GROUP BY id HAVING SUM(x) > 2 LIMIT 5', 'me')).toContain('SELECT');
  });
});

describe('sqlGuard: identifiers and fields', () => {
  it('quoteDotted quotes every segment and refuses anything else', () => {
    expect(quoteDotted('a.b')).toBe('"a"."b"');
    expect(quoteDotted('a.*')).toBe('"a".*');
    for (const bad of ['a b', 'a"b', 'a.b.c.d', 'a;b', "a'b", '1a', 'a.', '.a', '']) expect(() => quoteDotted(bad)).toThrow(SqlGuardError);
  });
  it('fieldToSql: plain paths are quoted, expressions are validated', () => {
    expect(fieldToSql('name')).toBe('"name"');
    expect(fieldToSql('o.total')).toBe('"o"."total"');
    expect(fieldToSql('*')).toBe('*');
    expect(fieldToSql('COUNT(*)')).toBe('COUNT(*)');
    expect(() => fieldToSql('a; drop table x')).toThrow(SqlGuardError);
  });
  it('safeInt accepts bounded integers (and numeric strings) only', () => {
    expect(safeInt('10')).toBe(10);
    expect(safeInt(0)).toBe(0);
    for (const bad of ['1; DROP TABLE x', -1, 1.5, NaN, Infinity, 1e12, '', {}, null, '1e3']) expect(() => safeInt(bad as any)).toThrow(SqlGuardError);
  });
  it('assertSafeName allows dotted/relaxed names but never quote-like characters', () => {
    expect(assertSafeName('order_items')).toBe('order_items');
    expect(assertSafeName('Order Items')).toBe('Order Items');
    for (const bad of ['a"b', "a'b", 'a;b', 'a`b', 'a\\b', '', 'x'.repeat(200)]) expect(() => assertSafeName(bad)).toThrow(SqlGuardError);
  });
});

describe('sqlGuard: validateAst (every AST field that reaches SQL text)', () => {
  const base = () => ({ from: { resource: 'orders' }, select: ['id'], where: [{ column: 'id', operator: 'EQ', value: 1 }], limit: 5 });
  it('accepts a normal AST', () => {
    expect(() => validateAst({ ...base(), joins: [{ type: 'LEFT', resource: 'c', on: { left: 'orders.cid', operator: 'EQ', right: 'c.id' } }], groupBy: ['id'], orderBy: [{ column: 'id', direction: 'DESC' }] }, 't1')).not.toThrow();
    expect(() => validateAst({ ...base(), select: [{ aggregate: 'SUM', column: 'amount', alias: 'total' }, { window: 'ROW_NUMBER', partitionBy: ['a'], orderBy: [{ column: 'b', direction: 'ASC' }], alias: 'rn' }] }, 't1')).not.toThrow();
  });
  const MUTATIONS: [string, (a: any) => void][] = [
    ['from.resource quote break-out', (a) => { a.from.resource = 'orders"; DROP TABLE x; --'; }],
    ['from.source', (a) => { a.from.source = 'x; DROP'; }],
    ['alias', (a) => { a.from.alias = 'a" OR 1=1 --'; }],
    ['select string', (a) => { a.select = ['id, (SELECT password_hash FROM public.users)']; }],
    ['select expression', (a) => { a.select = [{ expression: "pg_sleep(5)" }]; }],
    ['select expression subquery', (a) => { a.select = [{ expression: '(SELECT 1)' }]; }],
    ['aggregate fn', (a) => { a.select = [{ aggregate: 'pg_sleep(5) --', column: 'x' }]; }],
    ['window fn', (a) => { a.select = [{ window: 'pg_sleep', alias: 'x' }]; }],
    ['select alias', (a) => { a.select = [{ column: 'id', alias: 'x" , (select 1) as "y' }]; }],
    ['where column', (a) => { a.where = [{ column: 'id; DROP TABLE x', operator: 'EQ', value: 1 }]; }],
    ['where operator', (a) => { a.where = [{ column: 'id', operator: '= 1 OR 1=1 --', value: 1 }]; }],
    ['where expression', (a) => { a.where = [{ expression: "1=1; DROP TABLE x" }]; }],
    ['where search column', (a) => { a.where = [{ search: { column: 'a;b', query: 'x' } }]; }],
    ['where value NUL', (a) => { a.where = [{ column: 'id', operator: 'EQ', value: 'a\u0000b' }]; }],
    ['groupBy', (a) => { a.groupBy = ['id; DROP TABLE x']; }],
    ['orderBy column', (a) => { a.orderBy = [{ column: 'id; DROP', direction: 'ASC' }]; }],
    ['orderBy direction', (a) => { a.orderBy = [{ column: 'id', direction: 'ASC; DROP TABLE x' }]; }],
    ['join.type', (a) => { a.joins = [{ type: 'INNER JOIN x ON 1=1; --', resource: 'c', on: { left: 'a.b', operator: 'EQ', right: 'c.d' } }]; }],
    ['join.resource', (a) => { a.joins = [{ type: 'INNER', resource: 'c"; DROP', on: { left: 'a.b', operator: 'EQ', right: 'c.d' } }]; }],
    ['join.on operator', (a) => { a.joins = [{ type: 'INNER', resource: 'c', on: { left: 'a.b', operator: '= 1 OR 1=1', right: 'c.d' } }]; }],
    ['join.on string', (a) => { a.joins = [{ type: 'INNER', resource: 'c', on: '1=1; DROP TABLE x' }]; }],
    ['limit', (a) => { a.limit = '5; DROP TABLE x'; }],
    ['offset', (a) => { a.offset = '1 UNION SELECT 1'; }],
    ['with.name', (a) => { a.with = [{ name: 'x"; DROP', columns: ['a'], base: { from: { resource: 't' } } }]; }],
    ['with.columns', (a) => { a.with = [{ name: 'x', columns: ['a) AS (SELECT 1); DROP TABLE y; --'], base: { from: { resource: 't' } } }]; }],
    ['union leg', (a) => { a.union = [{ from: { resource: 'x"; DROP' } }]; }],
    ['derived table', (a) => { a.from = { query: { from: { resource: 'x"; DROP' } } }; }],
  ];
  it.each(MUTATIONS)('rejects injection via %s (HTTP 400)', (_name, mutate) => {
    const a: any = base(); mutate(a);
    let status = 0;
    try { validateAst(a, 't1'); } catch (e: any) { status = e.status; }
    expect(status).toBe(400);
  });
  it('escapeAstLiterals doubles quotes in values only', () => {
    const out = escapeAstLiterals({ where: [{ column: "o'name", operator: 'EQ', value: "x' OR '1'='1" }, { search: { column: 'a', query: "it's" } }, { column: 'b', value: ["a'b", 3] }] });
    expect(out.where[0].value).toBe("x'' OR ''1''=''1");
    expect(out.where[0].column).toBe("o'name");
    expect(out.where[1].search.query).toBe("it''s");
    expect(out.where[2].value).toEqual(["a''b", 3]);
  });
});

describe('QueryEngineService.generateSql (legacy path) never emits caller text outside quoted identifiers / validated fragments', () => {
  const gen = (cfg: any) => QueryEngineService.generateSql('t1', cfg);
  const POISON = ['x"; DROP TABLE y; --', "x'; DROP TABLE y; --", 'x) UNION SELECT 1 --', '1; DROP TABLE y'];

  it('select / groupBy / orderBy / join.on / index columns / view query / CTE / column types reject injection', async () => {
    for (const p of POISON) {
      await expect(gen({ type: 'SELECT', table: 'o', select: [p], limit: 1 })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'o', select: ['id'], groupBy: [p], limit: 1 })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'o', select: ['id'], orderBy: [{ field: p, dir: 'ASC' }], limit: 1 })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'o', select: ['id'], joins: [{ type: 'INNER', table: 'c', on: p }], limit: 1 })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'o', select: ['id'], joins: [{ type: p as any, table: 'c', on: 'a.id = c.id' }], limit: 1 })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'o', select: ['id'], limit: p as any })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'o', select: ['id'], limit: 1, offset: p as any })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'CREATE_INDEX', table: 'o', indexDef: { name: 'i', columns: [p] } })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'CREATE_VIEW', table: 'o', viewDef: { name: 'v', query: p } })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'CREATE_TABLE', table: 'o', schemaDef: { columns: [{ name: 'a', type: p }] } })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'CREATE_TABLE', table: 'o', schemaDef: { columns: [{ name: 'a', type: 'int', constraints: p }] } })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'ALTER_TABLE', table: 'o', alterDef: { action: 'ADD_COLUMN', columnName: 'c', columnType: p } })).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'SELECT', table: 'cte', withRecursive: { name: p, baseQuery: 'SELECT 1', recursiveQuery: 'SELECT 1' }, select: ['*'], limit: 1 } as any)).rejects.toThrow();
      await expect(gen({ type: 'SELECT', table: 'cte', withRecursive: { name: 'cte', baseQuery: p, recursiveQuery: 'SELECT 1' }, select: ['*'], limit: 1 } as any)).rejects.toThrow(SqlGuardError);
      await expect(gen({ type: 'CREATE_SEQUENCE', table: 'o', sequenceDef: { name: 's', start: p as any } })).rejects.toThrow(SqlGuardError);
    }
  });

  it('column / table / index / view / sequence names are quoted with embedded quotes doubled (no break-out)', async () => {
    const ins = await gen({ type: 'INSERT', table: 'o', data: { 'a"b': 1, 'c': 2 } });
    expect(ins.sql).toContain('"a""b"');
    expect(ins.sql).not.toMatch(/"a"b"/);
    const upd = await gen({ type: 'UPDATE', table: 'o', data: { 'x" = 1; --': 1 }, filter: { id: 1 } });
    expect(upd.sql).toContain('"x"" = 1; --"');
    const tbl = await gen({ type: 'SELECT', table: 'o"; DROP TABLE y; --', select: ['*'], limit: 1 });
    expect(tbl.sql).toBe('SELECT * FROM "tenant_t1"."oDROPTABLEy" LIMIT 1'); // table names are reduced to [A-Za-z0-9_]
    const idx = await gen({ type: 'CREATE_INDEX', table: 'o', indexDef: { name: 'i"; DROP', columns: ['a'] } });
    expect(idx.sql).toContain('"i""; DROP"');
  });

  it('legitimate legacy configs still produce the same shape of SQL', async () => {
    const r = await gen({ type: 'SELECT', table: 'orders', select: ['id', 'o.total', 'COUNT(*) AS n', 'sum(amount)'], joins: [{ type: 'LEFT', table: 'cust', on: 'orders.cid = cust.id' }], groupBy: ['id'], orderBy: [{ field: 'id', dir: 'DESC' }], limit: 10, offset: 5, filter: { status: 'A' } });
    expect(r.sql).toBe('SELECT "id", "o"."total", COUNT(*) AS n, sum(amount) FROM "tenant_t1"."orders" LEFT JOIN "tenant_t1"."cust" ON orders.cid = cust.id WHERE "status" = $1 GROUP BY "id" ORDER BY "id" DESC LIMIT 10 OFFSET 5');
    expect(r.params).toEqual(['A']);
    const v = await gen({ type: 'CREATE_VIEW', table: 'o', viewDef: { name: 'v1', query: 'SELECT id FROM orders WHERE total > 10' } });
    expect(v.sql).toBe('CREATE VIEW "tenant_t1"."v1" AS SELECT id FROM orders WHERE total > 10');
    const t = await gen({ type: 'CREATE_TABLE', table: 'x', schemaDef: { columns: [{ name: 'id', type: 'SERIAL PRIMARY KEY' }, { name: 'n', type: 'VARCHAR(255)', constraints: 'NOT NULL DEFAULT \'x\'' }] } });
    expect(t.sql).toBe(`CREATE TABLE "tenant_t1"."x" ("id" SERIAL PRIMARY KEY, "n" VARCHAR(255) NOT NULL DEFAULT 'x')`);
  });

  it('the engine refuses a tenant id that is not a plain identifier (no silent "cleaning" into another tenant)', async () => {
    await expect(QueryEngineService.generateSql('a-b', { type: 'SELECT', table: 'o', select: ['*'], limit: 1 })).rejects.toThrow(/Invalid tenant id/);
  });
});

describe('QueryEngineService CALL resolution', () => {
  const resolve = (name: string, schema?: string) => (QueryEngineService as any).resolveCallTarget('t1', name, schema);
  it('maps into the tenant\'s own schemas', () => {
    expect(resolve('fn')).toBe('"tenant_t1"."fn"');
    expect(resolve('fn', 'sales')).toBe('"tenant_t1_sales"."fn"');
    expect(resolve('sales.fn')).toBe('"tenant_t1_sales"."fn"');
    expect(resolve('tenant_t1_sales.fn')).toBe('"tenant_t1_sales"."fn"');
    expect(resolve('tenant_t1.fn')).toBe('"tenant_t1"."fn"');
  });
  it.each(['fabric_admin.create_tenant_namespace', 'public.fn', 'pg_catalog.pg_sleep', 'information_schema.x', 'fabric_system.x', 'fabric_catalog.x', 'citus.x',
    'tenant_t2.fn', 'tenant_t2_sales.fn', 'a.b.c', 'fn"; DROP', 'fn()', 'fn;', 'a b'])('refuses %s', (name) => {
    expect(() => resolve(name)).toThrow();
  });
  it('refuses reserved explicit schemas', () => {
    for (const s of ['public', 'fabric_admin', 'pg_catalog']) expect(() => resolve('fn', s)).toThrow(/ACCESS DENIED/);
  });
});
